      const summaries = await Promise.all(
        allWorkspaces.map(async (ws) => {
          const problems = await storage.listProblems(ws.id);
          return {
            id: ws.id,
            name: ws.name,
            agentCount: ws.agents.length,
            problemCount: problems.length,
          };
        }),
