/**
 * Read-only WorkspaceCell queries (RFC 0001 §Operation surface).
 *
 * Pure functions over the aggregate state. `read_workspace_events` is NOT
 * here — the event journal is a Worker-side table and the replay authority;
 * queries here answer from the snapshot only.
 */

import type { JsonValue } from '../canonical-json.js';
import { rejection, type CelldRejection } from '../errors.js';
import type { CellWorkspaceState } from './state.js';

export type QueryOutcome =
  | { ok: true; result: Record<string, JsonValue> }
  | { ok: false; rejection: CelldRejection };

export function query(
  state: CellWorkspaceState | null,
  operation: string,
  actorId: string,
  payload: Record<string, JsonValue>,
): QueryOutcome {
  if (state === null) {
    return { ok: false, rejection: rejection('WORKSPACE_NOT_INITIALIZED', 'Workspace cell state is not initialized') };
  }
  if (state.members[actorId] === undefined) {
    return {
      ok: false,
      rejection: rejection('NOT_WORKSPACE_MEMBER', `Agent ${actorId} is not a member of workspace ${state.workspace.id}`),
    };
  }

  switch (operation) {
    case 'list_problems': {
      const status = payload.status;
      const problems = Object.values(state.problems)
        .filter(p => status === undefined || p.status === status)
        .sort((a, b) => a.createdAt.localeCompare(b.createdAt) || a.id.localeCompare(b.id));
      return { ok: true, result: { problems: problems as unknown as JsonValue, count: problems.length } };
    }
    case 'read_channel': {
      const problemId = payload.problemId;
      if (typeof problemId !== 'string' || problemId.length === 0) {
        return { ok: false, rejection: rejection('VALIDATION_FAILED', `'problemId' must be a non-empty string`) };
      }
      if (state.problems[problemId] === undefined) {
        return { ok: false, rejection: rejection('NOT_FOUND', `Problem not found: ${problemId}`, { problemId }) };
      }
      const all = state.channels[problemId] ?? [];
      const limit = typeof payload.limit === 'number' && payload.limit > 0 ? Math.floor(payload.limit) : undefined;
      const messages = limit === undefined ? all : all.slice(-limit);
      return {
        ok: true,
        result: { problemId, messages: messages as unknown as JsonValue, count: messages.length, total: all.length },
      };
    }
    case 'list_impacts': {
      const targetAgentId = payload.targetAgentId;
      const status = payload.status;
      const impacts = Object.values(state.impacts)
        .filter(i => targetAgentId === undefined || i.targetAgentId === targetAgentId)
        .filter(i => status === undefined || i.status === status)
        .sort((a, b) => a.detectedAt.localeCompare(b.detectedAt) || a.impactId.localeCompare(b.impactId));
      return { ok: true, result: { impacts: impacts as unknown as JsonValue, count: impacts.length } };
    }
    case 'workspace_status': {
      const problems = Object.values(state.problems);
      const byStatus: Record<string, number> = {};
      for (const p of problems) byStatus[p.status] = (byStatus[p.status] ?? 0) + 1;
      return {
        ok: true,
        result: {
          workspace: state.workspace as unknown as JsonValue,
          members: Object.values(state.members) as unknown as JsonValue,
          problemCounts: byStatus,
          problemCount: problems.length,
          intentCount: Object.keys(state.intents).length,
          pendingImpactCount: Object.values(state.impacts).filter(i => i.status === 'pending').length,
        },
      };
    }
    case 'workspace_digest': {
      const open = Object.values(state.problems).filter(p => p.status === 'open' || p.status === 'in-progress');
      const pendingImpacts = Object.values(state.impacts).filter(i => i.status === 'pending');
      return {
        ok: true,
        result: {
          workspace: state.workspace as unknown as JsonValue,
          members: Object.values(state.members) as unknown as JsonValue,
          activeProblems: open as unknown as JsonValue,
          pendingImpacts: pendingImpacts as unknown as JsonValue,
          recentMessages: Object.entries(state.channels)
            .flatMap(([problemId, messages]) => messages.slice(-3).map(m => ({ problemId, ...m })))
            .sort((a, b) => a.timestamp.localeCompare(b.timestamp))
            .slice(-10) as unknown as JsonValue,
        },
      };
    }
    default:
      return { ok: false, rejection: rejection('VALIDATION_FAILED', `Unknown cell query: ${operation}`, { operation }) };
  }
}
/**
 * Workspace backend routing registry (RFC 0001: "`$HUB_DATA_DIR/hub/
 * workspace-backends.json` is a crash-safe routing/provisioning index only —
 * never workspace-state authority").
 *
 * Entries move provisioning → active, keyed by the creating caller's command
 * ID, so a crashed `create_workspace` retry resumes the same workspace and
 * command rather than racing a second creator into stealing it. This module
 * owns only that routing index; it has no opinion about cell state.
 *
 * Every write mirrors the fsynced-temp-file + atomic-rename pattern in
 * src/hub/hub-storage-fs.ts (`writeJson`): rename alone is not a durability
 * barrier, so the temp file's content is fsynced before the rename, and the
 * containing directory is best-effort fsynced after it so the rename itself
 * survives a crash.
 */

import { readFile, open, rename, unlink, mkdir } from 'node:fs/promises';
import { join, dirname, basename } from 'node:path';
import { randomUUID } from 'node:crypto';
import { CelldError, rejection } from './errors.js';

export interface WorkspaceRoute {
  workspaceId: string;
  backend: 'celld';
  status: 'provisioning' | 'active';
  commandId: string;
  createdAt: string;
  activatedAt?: string;
}

export interface BackendRegistry {
  get(workspaceId: string): Promise<WorkspaceRoute | undefined>;
  list(): Promise<WorkspaceRoute[]>;
  findByCommandId(commandId: string): Promise<WorkspaceRoute | undefined>;
  /**
   * Atomic find-or-create keyed by the creating command's ID. The command-ID
   * lookup and the route write happen inside ONE serialized section: two
   * concurrent first attempts with the same command ID resolve to the SAME
   * route even though each caller minted its own candidate workspace ID —
   * looking up outside the serialized section is exactly the race that
   * produced two active workspaces for one idempotency key.
   */
  findOrBeginProvisioning(commandId: string, candidateWorkspaceId: string): Promise<WorkspaceRoute>;
  markActive(workspaceId: string): Promise<void>;
}

interface RegistryDocument {
  version: 1;
  routes: Record<string, WorkspaceRoute>;
}

// =============================================================================
// Crash-safe file I/O (mirrors hub-storage-fs.ts writeJson)
// =============================================================================

async function ensureDir(dir: string): Promise<void> {
  await mkdir(dir, { recursive: true });
}

async function fsyncDir(dir: string): Promise<void> {
  try {
    const handle = await open(dir, 'r');
    try {
      await handle.sync();
    } finally {
      await handle.close();
    }
  } catch {
    // best-effort — some platforms/filesystems don't support fsync-ing a
    // directory handle; that does not mean the write itself failed.
  }
}

async function writeTempFile(dir: string, prefix: string, content: string): Promise<string> {
  await ensureDir(dir);
  const tmpPath = join(dir, `.${prefix}.${process.pid}.${randomUUID()}.tmp`);
  const handle = await open(tmpPath, 'w');
  try {
    await handle.writeFile(content, 'utf-8');
    await handle.sync();
  } finally {
    await handle.close();
  }
  return tmpPath;
}

async function writeRegistryDocument(path: string, doc: RegistryDocument): Promise<void> {
  const dir = dirname(path);
  const tmpPath = await writeTempFile(dir, basename(path), JSON.stringify(doc, null, 2));
  try {
    await rename(tmpPath, path);
    await fsyncDir(dir);
  } catch (err) {
    await unlink(tmpPath).catch(() => {});
    throw err;
  }
}

/**
 * A missing file is a normal first-run outcome (empty registry). Any other
 * read failure — most importantly corrupt/truncated JSON, exactly what a
 * crashed write leaves behind if it landed outside the rename barrier above
 * — throws loudly naming the file, rather than silently returning an empty
 * registry that would let a second creator steal an already-provisioning
 * workspace.
 */
async function readRegistryDocument(path: string): Promise<RegistryDocument> {
  let content: string;
  try {
    content = await readFile(path, 'utf-8');
  } catch (err) {
    if ((err as NodeJS.ErrnoException)?.code === 'ENOENT') {
      return { version: 1, routes: {} };
    }
    throw err;
  }
  try {
    return JSON.parse(content) as RegistryDocument;
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    throw new Error(`celld backend registry file is corrupt: ${path} — ${message}`);
  }
}

